 PERFORM public.update_recipe(v.id,v.slug,v.title,v.excerpt,v.ingredients,$s5$[{"title":"丸鶏と骨抜きの道具を用意する","content":"皮、両脚、両翼がついた生の丸鶏を用意します。滑りにくいまな板、細い骨抜き包丁、調理ばさみ、食品用の太い針とひも、網付き天板、温度計を準備します。内臓は取り除き、鶏肉を冷蔵し、水洗いしません。焼く直前にオーブンを180°Cに予熱します。骨抜きに不慣れなら2・3の手順で指定する骨だけを精肉店で抜いてもらいます。","image_alt":"コロンビア風クリスマスの丸鶏の詰め物焼き — 丸鶏と骨抜きの道具を用意する","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-01.webp"},{"title":"鶏を開かず胴体の骨格を取り出す","content":"後部の空洞から作業し、肋骨、背骨、胸骨に沿って短い切れ目を入れながら肉を骨から外します。背中を縦に切り開いたり皮を傷つけたりせず、肩と股関節の接続部分を外し、脚と翼は胴体につながったままにします。胴体の骨格を取り出して骨片がないか確認します。翼の付け根側の骨も慎重に除き、翼先端の骨は残します。","image_alt":"コロンビア風クリスマスの丸鶏の詰め物焼き — 鶏を開かず胴体の骨格を取り出す","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-02.webp"},{"title":"上ももの大腿骨だけを抜き、下側の脚の骨は残す","content":"左右の脚の付け根から上ももの大腿骨を探し、皮を破らないよう肉を外します。股関節と膝関節から骨を切り離し、両側の大腿骨を抜き取ります。下側のすね（ドラムスティック）の骨と翼の先端の骨は残してください。上ももにできた左右の空洞には後で詰め物を入れます。縫うための小さな開口部を残し、骨の欠片を取り除きます。","image_alt":"コロンビア風クリスマスの丸鶏の詰め物焼き — 上ももの大腿骨だけを抜き、下側の脚の骨は残す","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-03.webp"},{"title":"野菜、レーズン、好みのグリーンピースを準備する","content":"にんじん角切り100 gを軽く下ゆでして冷まし、使う場合はグリーンピース100 gも加熱して水気を切ります。レーズン90 gをぬるま湯に10分浸して水を切ります。玉ねぎ100 gと赤パプリカ80 gを油10 gで約5分炒め、にんにく12 gを加えて30秒炒めます。生ひき肉と混ぜる前に完全に冷ましてください。","image_alt":"コロンビア風クリスマスの丸鶏の詰め物焼き — 野菜、レーズン、好みのグリーンピースを準備する","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-04.webp"},{"title":"牛・豚ひき肉、パン粉、レーズンを混ぜる","content":"牛ひき肉300 g、豚ひき肉300 g、味付けなしのパン粉80 g、溶き卵1個（50 g）を混ぜます。水を切ったレーズン、冷ました野菜、好みでグリーンピース、パセリ12 g、塩・こしょう・クミン・パプリカの半量を加えます。練りすぎず、低温で扱い、二次汚染を防いでください。","image_alt":"コロンビア風クリスマスの丸鶏の詰め物焼き — 牛・豚ひき肉、パン粉、レーズンを混ぜる","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-05.webp"},{"title":"左右両方の骨抜きした上ももに詰め、縫う","content":"大腿骨を抜いた左右の上ももの空洞に肉だねを少しずつ詰め、自然な太さを取り戻します。骨が残る下側のすねへ無理に押し込まず、皮も引っ張りすぎないでください。食品用の針とひもで、上ももから下側の脚へ続く骨抜きの小さな開口部や切れ目を縫い閉じます。脚は胴体につけたままです。","image_alt":"コロンビア風クリスマスの丸鶏の詰め物焼き — 左右両方の骨抜きした上ももに詰め、縫う","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-06-v2.webp"},{"title":"胴体の後部に詰め、開口部を縫う","content":"残りの肉だねを胴体後部の空洞から少しずつ詰めます。皮が裂けないよう詰めすぎず、首側が開いていれば先に縫い、後部の入口も食品用ひもでしっかり縫い閉じます。左右の上ももの縫い目も確認します。余った肉だねは別皿で中心74°C以上まで加熱してください。","image_alt":"コロンビア風クリスマスの丸鶏の詰め物焼き — 胴体の後部に詰め、開口部を縫う","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-07-v2.webp"},{"title":"脚と翼を固定し、丸鶏のまま焼く","content":"下側のすねと翼先端の骨はそのまま残します。翼を体に寄せ、脚を自然な位置で軽く縛ります。残りの油10 gに塩・こしょう・クミン・パプリカの残り半量を混ぜて皮に塗り、同じ網付き天板に胸を上にして置きます。180°Cで約105～150分、重さと詰め物の厚みに応じて加熱します。色づきが早ければホイルをふんわりかけます。時間だけで安全性は判断できません。","image_alt":"コロンビア風クリスマスの丸鶏の詰め物焼き — 脚と翼を固定し、丸鶏のまま焼く","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-08.webp"},{"title":"胴体と左右の上ももの詰め物が74°C以上か測る","content":"清潔な食品用温度計で胸肉の最も厚い部分、胴体の詰め物の中心、左右の上ももの詰め物の中心をそれぞれ測ります。下側のすねや翼先端に残した骨には温度計を当てないでください。鶏肉と詰め物のすべての測定部位が74°C以上になるまで焼き、低ければ再加熱して測り直します。","image_alt":"コロンビア風クリスマスの丸鶏の詰め物焼き — 胴体と左右の上ももの詰め物が74°C以上か測る","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-09.webp"},{"title":"休ませて胴体を横方向にきれいに輪切りする","content":"丸鶏のまま清潔なまな板で15分休ませます。後部、首、左右の上ももに使った縫い糸と固定ひもをすべて外してください。骨が残る下側の脚や翼先端は、包丁の邪魔になる場合は切り分けます。胴体を縦に開かず横方向に厚さ2～3 cmの均等な輪切りにし、牛・豚肉、レーズン、野菜の詰め物を崩さず整えて並べます。残りは2時間以内、気温32°C超なら1時間以内に冷蔵してください。","image_alt":"コロンビア風クリスマスの丸鶏の詰め物焼き — 休ませて胴体を横方向にきれいに輪切りする","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-10.webp"}]$s5$::jsonb,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,true);
 n:=n+1;
 SELECT * INTO STRICT v FROM public.recipes WHERE id='94b866bd-c1ba-419c-b213-8eb108e96c03' FOR UPDATE;
 IF v.updated_at <> '2026-11-09 03:54:48.523747+00'::timestamptz THEN RAISE EXCEPTION 'Concurrent edit: pt'; END IF;
 PERFORM public.update_recipe(v.id,v.slug,v.title,v.excerpt,v.ingredients,$s6$[{"title":"Prepare o frango inteiro e as ferramentas","content":"Comece com um frango cru inteiro com pele, pernas e asas presas. Separe tábua antiderrapante, faca estreita de desossa afiada, tesoura, agulha grande e linha culinária adequadas, grade, assadeira e termômetro. Retire os miúdos, mantenha o frango refrigerado e não o lave. Preaqueça o forno a 180 °C pouco antes de assar. Se necessário, peça ao açougueiro que retire apenas os ossos dos passos 2 e 3.","image_alt":"Frango recheado de Natal colombiano com carne bovina e suína — Prepare o frango inteiro e as ferramentas","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-01.webp"},{"title":"Retire a carcaça pelo interior sem abrir o corpo","content":"Trabalhe a partir da cavidade traseira, separando delicadamente a carne das costelas, coluna e esterno com movimentos curtos da faca junto aos ossos. Não perfure a pele nem abra as costas como uma manta. Solte as articulações dos ombros e quadris, preservando pernas e asas ligadas. Retire a carcaça e confira se não há lascas. Retire com cuidado os ossos próximos ao corpo das asas, deixando os ossos das pontas.","image_alt":"Frango recheado de Natal colombiano com carne bovina e suína — Retire a carcaça pelo interior sem abrir o corpo","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-02.webp"},{"title":"Retire somente o fêmur das SOBRECOXAS, mantendo ossos das coxas inferiores","content":"Pelo interior, encontre o osso superior de cada SOBRECOXA (fêmur), desprenda delicadamente a carne sem rasgar a pele e libere o osso no quadril e na articulação com a coxa inferior. Retire os dois fêmures. Deixe os ossos das COXAS INFERIORES e das pontas das asas. As duas sobrecoxas ficam com cavidades que receberão recheio; conserve as pequenas aberturas para costurar e remova lascas ósseas.","image_alt":"Frango recheado de Natal colombiano com carne bovina e suína — Retire somente o fêmur das SOBRECOXAS, mantendo ossos das coxas inferiores","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-03.webp"},{"title":"Prepare legumes, passas e ervilhas opcionais","content":"Pré-cozinhe 100 g de cenoura em cubos até ficar macia, escorra e esfrie. Cozinhe e escorra 100 g de ervilhas se usar. Hidrate 90 g de passas em água morna por 10 minutos e escorra. Refogue 100 g de cebola e 80 g de pimentão vermelho com 10 g de óleo por 5 minutos, adicione 12 g de alho por 30 segundos. Deixe esfriar completamente antes de juntar à carne crua.","image_alt":"Frango recheado de Natal colombiano com carne bovina e suína — Prepare legumes, passas e ervilhas opcionais","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-04.webp"},{"title":"Misture carnes bovina e suína, farinha de rosca e passas","content":"Misture 300 g de carne bovina moída, 300 g de carne suína moída, 80 g de farinha de rosca sem tempero e 1 ovo batido (50 g). Acrescente passas, legumes frios, ervilhas opcionais, 12 g de salsinha e metade do sal, pimenta, cominho e páprica. Misture só até incorporar, mantenha frio e evite contaminação cruzada.","image_alt":"Frango recheado de Natal colombiano com carne bovina e suína — Misture carnes bovina e suína, farinha de rosca e passas","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-05.webp"},{"title":"Recheie as DUAS sobrecoxas e costure as aberturas","content":"Coloque porções do recheio nas cavidades deixadas pelos fêmures das DUAS sobrecoxas, devolvendo volume sem empurrar mistura para dentro das coxas inferiores que ainda têm ossos, nem forçar a pele. Costure com agulha e linha culinária próprias para alimentos as pequenas aberturas perto da ligação com as coxas inferiores e os demais cortes de desossa. As pernas continuam ligadas ao corpo.","image_alt":"Frango recheado de Natal colombiano com carne bovina e suína — Recheie as DUAS sobrecoxas e costure as aberturas","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-06-v2.webp"},{"title":"Recheie o corpo e costure a abertura traseira","content":"Coloque o restante da mistura pela cavidade posterior, distribuindo sem apertar demais. Feche com pontos a abertura do pescoço se estiver aberta e costure firmemente a cavidade traseira. Confira também as duas costuras das SOBRECOXAS. Asse qualquer recheio sobrando separadamente até atingir pelo menos 74 °C no centro; não sobrecarregue a pele.","image_alt":"Frango recheado de Natal colombiano com carne bovina e suína — Recheie o corpo e costure a abertura traseira","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-07-v2.webp"},{"title":"Amarre pernas e asas e asse o frango inteiro","content":"Não retire os ossos das coxas inferiores nem das pontas das asas. Prenda levemente as asas junto ao corpo e as pernas na posição natural. Misture os últimos 10 g de óleo com a outra metade do sal, pimenta, cominho e páprica e pincele a pele, coloque com o peito para cima na grade da mesma assadeira e asse a 180 °C por cerca de 105–150 minutos conforme tamanho e espessura. Cubra frouxamente com alumínio se dourar cedo demais. O tempo sozinho não garante a segurança.","image_alt":"Frango recheado de Natal colombiano com carne bovina e suína — Amarre pernas e asas e asse o frango inteiro","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-08.webp"},{"title":"Confira 74 °C na carne e nas TRÊS cavidades recheadas","content":"Use termômetro limpo na parte mais grossa do peito, no centro do recheio do corpo e no centro de cada uma das DUAS sobrecoxas recheadas. Não encoste nos ossos que ficaram nas coxas inferiores ou pontas das asas. O frango e cada porção de recheio devem atingir pelo menos 74 °C; se algum ponto estiver abaixo, continue assando e meça novamente.","image_alt":"Frango recheado de Natal colombiano com carne bovina e suína — Confira 74 °C na carne e nas TRÊS cavidades recheadas","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-09.webp"},{"title":"Descanse e corte fatias transversais bem definidas","content":"Deixe o frango inteiro descansar 15 minutos em uma tábua limpa. Retire TODAS as linhas da abertura traseira, pescoço e das duas sobrecoxas, além dos barbantes. As coxas inferiores e pontas das asas ainda têm ossos e podem ser separadas na hora de cortar. Fatie o corpo TRANSVERSALMENTE em porções uniformes de 2–3 cm, sem abrir no comprimento, e arrume as fatias perto da ave com o recheio compacto intacto. Refrigere sobras em até 2 horas (1 hora se o ambiente superar 32 °C).","image_alt":"Frango recheado de Natal colombiano com carne bovina e suína — Descanse e corte fatias transversais bem definidas","image_url":"https://manualdecocina.com/recetas/pollo-relleno-navideno/paso-10.webp"}]$s6$::jsonb,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,true);
 n:=n+1;
 IF EXISTS(SELECT 1 FROM public.recipe_ingredient_pending WHERE recipe_id='0c8a361b-cb9a-424b-adc2-e27ae183062f') OR (SELECT count(*) FROM public.recipe_ingredients WHERE recipe_id='0c8a361b-cb9a-424b-adc2-e27ae183062f')<>17 THEN RAISE EXCEPTION 'Unresolved ingredient links'; END IF;
 IF n<>7 THEN RAISE EXCEPTION 'Incomplete publication'; END IF;
END $publish$;
SELECT language,public_path,published,jsonb_array_length(steps) as steps,(select count(*) from jsonb_array_elements(steps) s where coalesce(s->>'image_url','')<>'') as photos FROM recipes WHERE recipe_group_id='9cd4fa16-5d2b-44ef-afcb-68322a55efd1' order by language;
